script_matches=re.findall(r'<script[^>]*type="application/json"[^>]*>(.*?)</script>',original_page,re.S)
original_models=[json.loads(s) for s in script_matches]
def find_objects(value,predicate):
 found=[]
 if isinstance(value,dict):
  if predicate(value): found.append(value)
  for v in value.values(): found+=find_objects(v,predicate)
 elif isinstance(value,list):
  for v in value: found+=find_objects(v,predicate)
 return found
