product = inventory['source_hashes']
integrity = {'authority':BASE+'tasks/M01/planning/s2-green/source-current.json','authority_inventory_head':inventory['head'],'current_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'count':len(product),'mismatches':[p for p,h in product.items() if not (ROOT/p).is_file() or sha(p)!=h]}
